script:
frappe.ui.form.on("WMS ASN", {
  refresh(frm) {
    frm.add_custom_button("Import from Excel", () => {
      new frappe.ui.FileUploader({
        doctype: frm.doctype,
        docname: frm.docname,
        folder: "Home",
        restrictions: { allowed_file_types: [".xlsx"] },
        on_success(file) {
          frappe.call({
            method: "printechs_wms.api.asn_import_ui.import_wms_asn_excel",
            args: {
              file_url: file.file_url,
              submit: 0
            },
            freeze: true,
            freeze_message: "Importing ASN from Excel...",
            callback(r) {
              const res = r.message || {};
              if (res.errors && res.errors.length) {
                frappe.msgprint({
                  title: "Import Completed with Errors",
                  message: "<pre>" + JSON.stringify(res, null, 2) + "</pre>",
                  indicator: "orange"
                });
              } else {
                frappe.msgprint({
                  title: "Import Success",
                  message: `Created ${res.count} ASN(s): ${(res.created || []).join(", ")}`,
                  indicator: "green"
                });
              }
              frm.reload_doc();
            }
          });
        }
      });
    });
  }
});

frappe.ui.form.on("WMS Transfer Order", {
  refresh(frm) {
    frm.add_custom_button("Import TO", () => {
      new frappe.ui.FileUploader({
        doctype: frm.doctype,
        docname: frm.docname,
        folder: "Home",
        restrictions: { allowed_file_types: [".xlsx"] },

        on_success(file) {
          frappe.call({
            // ✅ CHANGE THIS to your real method path (the new header+detail TO import)
            method: "printechs_wms.api.transfer_order_import.import_transfer_order_from_excel",
            args: {
              file_url: file.file_url,
              sheet_name: "WMS Transfer Order", // header sheet
              create_new: 1,                    // 1=create (or update safely), 0=force update existing by name/to_title
              submit: 0
            },
            freeze: true,
            freeze_message: "Importing Transfer Order from Excel...",
            callback(r) {
              const res = r.message || {};

              // show full result if errors exist
              if (res.errors && res.errors.length) {
                frappe.msgprint({
                  title: "Import Completed with Errors",
                  message: "<pre>" + JSON.stringify(res, null, 2) + "</pre>",
                  indicator: "orange"
                });
              } else {
                frappe.msgprint({
                  title: "Import Success",
                  message: `
                    Total Item Lines: ${res.total_items || 0}<br>
                    Created: ${(res.created || []).join(", ") || "-"}<br>
                    Updated: ${(res.updated || []).join(", ") || "-"}<br>
                  `,
                  indicator: "green"
                });
              }

              // If API returns first_to, open it
              if (res.first_to) {
                frappe.set_route("Form", "WMS Transfer Order", res.first_to);
              } else {
                frm.reload_doc();
              }
            }
          });
        }
      });
    });
  }
});

frappe.ui.form.on("Item", {
  refresh(frm) {
    if (frm.is_new()) return;

    frm.add_custom_button(__("WMS Stock by Location / Carton"), async () => {
      const d = await frappe.prompt(
        [
          {
            fieldname: "location",
            fieldtype: "Data",   // ✅ FIXED (was Link)
            label: "Bin Location",
            reqd: 0
          },
          {
            fieldname: "carton_id",
            fieldtype: "Data",
            label: "Carton ID",
            reqd: 0
          },
          {
            fieldname: "show_zero",
            fieldtype: "Check",
            label: "Include Zero Qty",
            default: 0
          }
        ],
        __("Filter WMS Stock"),
        __("Open")
      );

      const filters = {
        item_code: frm.doc.item_code
      };

      if (d.location) {
        filters.location = d.location;   // fieldname in WMS Stock Balance
      }

      if (d.carton_id) {
        filters.carton = d.carton_id;
      }

      if (!d.show_zero) {
        filters.qty = [">", 0];
      }

      frappe.set_route("List", "WMS Stock Balance", filters);
    });
  }
});

const WMS_DRILLDOWN_PANEL_SEL = "#wms_drilldown_panel, .wms-drilldown-panel";

function wms_dashboard_scope(frm) {
  const $dash = frm.dashboard && frm.dashboard.parent;
  return $dash && $dash.length ? $dash : frm.$wrapper;
}

function wms_is_dashboard_tab_active(frm) {
  const tab = frm.get_active_tab && frm.get_active_tab();
  return !!(tab && tab.df && tab.df.fieldname === "dashboard_tab");
}

function wms_bump_drilldown_generation(frm) {
  frm.wms_drilldown_generation = (frm.wms_drilldown_generation || 0) + 1;
  return frm.wms_drilldown_generation;
}

function wms_teardown_drilldown_panel(frm) {
  if (frm && frm.wms_drilldown_timer) {
    clearInterval(frm.wms_drilldown_timer);
    frm.wms_drilldown_timer = null;
  }
  if (frm) {
    frm.wms_drilldown_warehouse = null;
  }
  wms_dashboard_scope(frm).find(WMS_DRILLDOWN_PANEL_SEL).remove();
  $(WMS_DRILLDOWN_PANEL_SEL).remove();
}

function wms_panel_item_code(frm) {
  const $panel = wms_dashboard_scope(frm).find("#wms_drilldown_panel").first();
  return ($panel.attr("data-item-code") || "").trim();
}

function wms_reset_drilldown_panel(frm) {
  const item = frm.doc.item_code || "";
  const $scope = wms_dashboard_scope(frm);
  const $panel = $scope.find("#wms_drilldown_panel").first();
  if (!$panel.length) {
    frm.wms_drilldown_warehouse = null;
    return;
  }
  $panel.attr("data-item-code", item);
  frm.wms_drilldown_warehouse = null;
  $panel.find("#wms_drilldown_title").text(
    item ? `Item: ${item} — click a Warehouse row above` : "Click a Warehouse row above"
  );
  $panel.find("#wms_drilldown_body").html('<div class="text-muted">No warehouse selected.</div>');
}

async function wms_load_drilldown(frm, warehouse_name) {
  const item_code = frm.doc.item_code;
  if (!item_code || !warehouse_name) return;

  const generation = frm.wms_drilldown_generation || 0;
  frm.wms_drilldown_warehouse = warehouse_name;

  const $scope = wms_dashboard_scope(frm);
  const $panel = $scope.find("#wms_drilldown_panel").first();
  if (!$panel.length) return;
  $panel.attr("data-item-code", item_code);

  $panel.find("#wms_drilldown_title").text(`Item: ${item_code} | Warehouse: ${warehouse_name}`);
  $panel.find("#wms_drilldown_body").html('<div class="text-muted">Loading WMS stock...</div>');

  try {
    const resp = await frappe.call({
      method: "printechs_wms.api.wms_stock_drilldown.get_item_location_carton_balance",
      args: {
        item_code,
        warehouse: warehouse_name,
        company: frm.doc.company || null,
        limit: 500,
      },
    });

    if ((frm.wms_drilldown_generation || 0) !== generation) return;
    if (frm.doc.item_code !== item_code) return;
    if (frm.wms_drilldown_warehouse !== warehouse_name) return;
    if (!$panel.length || $panel.attr("data-item-code") !== item_code) return;

    const rows = (resp.message && resp.message.rows) ? resp.message.rows : [];

    if (!rows.length) {
      $panel.find("#wms_drilldown_body").html(
        '<div class="text-muted">No WMS stock found for this item in the selected warehouse.</div>'
      );
      return;
    }

    const esc = (v) => frappe.utils.escape_html(String(v ?? ""));
    const n = (v) => (v === null || v === undefined ? 0 : Number(v) || 0);

    let html = `
      <div style="overflow:auto;">
        <table class="table table-bordered table-hover">
          <thead>
            <tr>
              <th>Location ID</th>
              <th>Carton ID</th>
              <th class="text-right">Balance</th>
              <th class="text-right">Reserved</th>
              <th class="text-right">Available</th>
              <th>Last Txn</th>
            </tr>
          </thead>
          <tbody>
    `;

    rows.forEach((r) => {
      html += `
        <tr>
          <td>${esc(r.location || "")}</td>
          <td>${esc(r.carton || "")}</td>
          <td class="text-right"><b>${esc(n(r.balance))}</b></td>
          <td class="text-right">${esc(n(r.reserved))}</td>
          <td class="text-right"><b>${esc(n(r.available))}</b></td>
          <td>${esc(r.last_txn_datetime || "")}</td>
        </tr>
      `;
    });

    html += "</tbody></table></div>";
    $panel.find("#wms_drilldown_body").html(html);
  } catch (err) {
    if ((frm.wms_drilldown_generation || 0) !== generation) return;
    console.error(err);
    $panel.find("#wms_drilldown_body").html('<div class="text-danger">Failed to load WMS stock. Check server logs.</div>');
  }
}

function wms_bind_dashboard_tab_click(frm) {
  frm.$wrapper
    .find('.form-tabs .nav-link[data-fieldname="dashboard_tab"]')
    .off("click.wms_drilldown")
    .on("click.wms_drilldown", () => {
      wms_bump_drilldown_generation(frm);
      wms_teardown_drilldown_panel(frm);
    });
}

function wms_on_dashboard_tab_activate(frm) {
  if (frm.is_new()) return;
  wms_bump_drilldown_generation(frm);
  wms_teardown_drilldown_panel(frm);
  frm.wms_drilldown_item_code = frm.doc.item_code;
  frm.trigger("wms_attach_stock_levels_drilldown");
}

function wms_sync_drilldown_with_current_item(frm) {
  const current = (frm.doc.item_code || "").trim();
  const panel_item = wms_panel_item_code(frm);
  if (panel_item && panel_item !== current) {
    wms_on_dashboard_tab_activate(frm);
    return true;
  }
  return false;
}

frappe.ui.form.on("Item", {
  refresh(frm) {
    wms_bind_dashboard_tab_click(frm);
    wms_bump_drilldown_generation(frm);
    wms_teardown_drilldown_panel(frm);

    if (frm.is_new()) return;

    frm.wms_drilldown_item_code = frm.doc.item_code;

    if (wms_is_dashboard_tab_active(frm)) {
      wms_on_dashboard_tab_activate(frm);
    }

    setTimeout(() => {
      if (wms_is_dashboard_tab_active(frm)) wms_sync_drilldown_with_current_item(frm);
    }, 400);
    setTimeout(() => {
      if (wms_is_dashboard_tab_active(frm)) wms_sync_drilldown_with_current_item(frm);
    }, 1200);
  },

  on_tab_change(frm) {
    if (wms_is_dashboard_tab_active(frm)) {
      wms_on_dashboard_tab_activate(frm);
    }
  },

  onload(frm) {
    wms_bump_drilldown_generation(frm);
    wms_teardown_drilldown_panel(frm);
    frm.wms_drilldown_item_code = frm.doc.item_code;
  },

  wms_attach_stock_levels_drilldown(frm) {
    if (frm.wms_drilldown_timer) {
      clearInterval(frm.wms_drilldown_timer);
      frm.wms_drilldown_timer = null;
    }

    const expected_item = (frm.doc.item_code || "").trim();
    let attempts = 0;
    const $scope = wms_dashboard_scope(frm);

    frm.wms_drilldown_timer = setInterval(() => {
      attempts++;

      if ((frm.doc.item_code || "").trim() !== expected_item) {
        clearInterval(frm.wms_drilldown_timer);
        frm.wms_drilldown_timer = null;
        return;
      }

      const $title = $scope
        .find("h3, h4, div")
        .filter(function () {
          return ($(this).text() || "").trim() === "Stock Levels";
        })
        .first();

      if (!$title.length) {
        if (attempts >= 30) {
          clearInterval(frm.wms_drilldown_timer);
          frm.wms_drilldown_timer = null;
        }
        return;
      }

      const $block = $title.closest(
        ".frappe-card, .form-dashboard-section, .section-body, .widget, .form-section"
      );

      if (!$block.length) {
        if (attempts >= 30) {
          clearInterval(frm.wms_drilldown_timer);
          frm.wms_drilldown_timer = null;
        }
        return;
      }

      $scope.find(WMS_DRILLDOWN_PANEL_SEL).remove();

      const panel = $(`
        <div id="wms_drilldown_panel" class="frappe-card wms-drilldown-panel" style="margin-top:12px; padding:12px;" data-item-code="${frappe.utils.escape_html(expected_item)}">
          <div style="display:flex; justify-content:space-between; align-items:center;">
            <b>WMS Stock Drilldown</b>
            <span class="text-muted" id="wms_drilldown_title">Click a Warehouse row above</span>
          </div>
          <div id="wms_drilldown_body" style="margin-top:10px;">
            <div class="text-muted">No warehouse selected.</div>
          </div>
        </div>
      `);
      $block.after(panel);
      wms_reset_drilldown_panel(frm);

      $block.off("click.wms");
      $block.on("click.wms", "a", async (e) => {
        const warehouse_name = (e.target && e.target.innerText) ? e.target.innerText.trim() : "";
        if (!warehouse_name || !warehouse_name.includes(" - ")) return;

        e.preventDefault();
        e.stopPropagation();
        await wms_load_drilldown(frm, warehouse_name);
      });

      clearInterval(frm.wms_drilldown_timer);
      frm.wms_drilldown_timer = null;
    }, 200);
  },
});

frappe.ui.form.on('WMS Cycle Count Batch', {
  refresh(frm) {
    if (frm.is_new()) return;

    // Preview button
    if (frm.doc.status !== "Posted") {
      frm.add_custom_button("Load Actual Stock Preview", () => {
        frappe.call({
          method: "printechs_wms.api.cycle_count_batch.load_actual_stock_preview",
          args: { batch_name: frm.doc.name },
          freeze: true,
          callback: (r) => {
            if (r.message && r.message.ok) {
              frappe.msgprint(`Preview done. Updated lines: ${r.message.updated_lines}, Summary rows: ${r.message.summary_rows}`);
              frm.reload_doc();
            } else {
              frappe.msgprint(JSON.stringify(r.message || r, null, 2));
            }
          }
        });
      });
    }

    // Confirm & Post button
    if (frm.doc.status === "Previewed") {
      frm.add_custom_button("Confirm & Post Batch", () => {
        frappe.confirm(
          "This will update WMS Stock Balance and (optionally) create Stock Reconciliation. Continue?",
          () => {
            frappe.call({
              method: "printechs_wms.api.cycle_count_batch.confirm_and_post_batch",
              args: { batch_name: frm.doc.name, create_stock_reconciliation: 1 },
              freeze: true,
              callback: (r) => {
                if (r.message && r.message.ok) {
                  frappe.msgprint(`Posted. Updated balances: ${r.message.updated_balances}. SR: ${r.message.stock_reconciliation || "Not created"}`);
                  frm.reload_doc();
                } else {
                  frappe.msgprint(JSON.stringify(r.message || r, null, 2));
                }
              }
            });
          }
        );
      }).addClass("btn-primary");
    }
  }
});

// WMS Cycle Count Batch — linked tasks panel + reconciliation workflow

const WMS_BATCH_TASKS_PANEL = ".wms-batch-tasks-panel";

function wms_remove_batch_tasks_panel(frm) {
	frm.$wrapper.find(WMS_BATCH_TASKS_PANEL).remove();
}

function wms_status_indicator(status) {
	const map = {
		Posted: "green",
		Completed: "blue",
		Validated: "blue",
		"In Progress": "orange",
		Open: "grey",
		Cancelled: "red",
		Closed: "grey",
	};
	return map[status] || "grey";
}

function wms_paint_batch_tasks_panel(frm, $panel, data) {
	const batch_status = data.batch_status || frm.doc.status || "Draft";
	const editable = batch_status !== "Posted";
	const tasks = data.tasks || [];

	let rows_html = "";
	if (!tasks.length) {
		rows_html = `<tr><td colspan="7" class="text-muted">${__("No linked count tasks yet. Mobile pushes will appear here.")}</td></tr>`;
	} else {
		for (const task of tasks) {
			const is_posted = task.status === "Posted";
			const checked = task.include_in_post ? "checked" : "";
			const disabled = !editable || is_posted ? "disabled" : "";
			const row_class = is_posted ? "text-muted" : "";
			const task_link = frappe.utils.get_form_link("WMS Cycle Count Task", task.name, true);
			const include_cell = is_posted
				? `<span class="indicator-pill ${task.include_in_post ? "green" : "grey"}">${task.include_in_post ? __("Yes") : __("No")}</span>`
				: `<input type="checkbox" class="wms-task-include" data-task="${frappe.utils.escape_html(task.name)}" ${checked} ${disabled}>`;

			rows_html += `
				<tr class="${row_class}" data-task="${frappe.utils.escape_html(task.name)}">
					<td style="width:40px;text-align:center;">${include_cell}</td>
					<td>${task_link}</td>
					<td>${frappe.datetime.str_to_user(task.posting_date) || "-"}</td>
					<td><span class="indicator-pill ${wms_status_indicator(task.status)}">${__(task.status || "-")}</span></td>
					<td>${__(task.count_mode || "-")}</td>
					<td class="text-right">${task.line_count || 0}</td>
					<td>${frappe.utils.escape_html(task.external_ref || "-")}</td>
				</tr>`;
		}
	}

	const toolbar = editable
		? `<div class="flex justify-between align-center" style="margin-bottom:8px;">
				<div class="text-muted">${__("{0} task(s) linked · {1} included for post · {2} pending", [
					data.total || 0,
					data.included_count || 0,
					data.pending_count || 0,
				])}</div>
				<div>
					<button type="button" class="btn btn-xs btn-default wms-select-all-tasks">${__("Select All Pending")}</button>
					<button type="button" class="btn btn-xs btn-default wms-clear-all-tasks">${__("Clear Selection")}</button>
				</div>
			</div>`
		: `<div class="text-muted" style="margin-bottom:8px;">${__("{0} linked task(s)", [data.total || 0])}</div>`;

	$panel.html(`
		<div class="section-head collapsible">
			<span>${__("Linked Count Tasks")}</span>
		</div>
		<div class="section-body">
			<p class="text-muted small">${__(
				"Check tasks to include in Preview and Post. Posted tasks are skipped automatically. Different posting dates can share one batch."
			)}</p>
			${toolbar}
			<div class="table-responsive">
				<table class="table table-bordered table-sm wms-batch-tasks-table">
					<thead>
						<tr>
							<th>${__("Include")}</th>
							<th>${__("Task")}</th>
							<th>${__("Posting Date")}</th>
							<th>${__("Status")}</th>
							<th>${__("Count Mode")}</th>
							<th class="text-right">${__("Lines")}</th>
							<th>${__("External Ref")}</th>
						</tr>
					</thead>
					<tbody>${rows_html}</tbody>
				</table>
			</div>
		</div>
	`);

	$panel.find(".wms-task-include").on("change", function () {
		const task_name = $(this).data("task");
		const include = $(this).is(":checked") ? 1 : 0;
		wms_save_batch_task_inclusion(frm, [{ name: task_name, include_in_post: include }], $panel);
	});

	$panel.find(".wms-select-all-tasks").on("click", () => {
		const selections = tasks
			.filter((t) => t.status !== "Posted")
			.map((t) => ({ name: t.name, include_in_post: 1 }));
		if (!selections.length) return;
		wms_save_batch_task_inclusion(frm, selections, $panel, true);
	});

	$panel.find(".wms-clear-all-tasks").on("click", () => {
		const selections = tasks
			.filter((t) => t.status !== "Posted")
			.map((t) => ({ name: t.name, include_in_post: 0 }));
		if (!selections.length) return;
		wms_save_batch_task_inclusion(frm, selections, $panel, true);
	});
}

function wms_save_batch_task_inclusion(frm, selections, $panel, reload_panel = false) {
	frappe.call({
		method: "printechs_wms.api.cycle_count_batch.set_batch_task_inclusion",
		args: {
			batch_name: frm.doc.name,
			selections: JSON.stringify(selections),
		},
		freeze: true,
		freeze_message: __("Saving task selection..."),
		callback: (r) => {
			const m = r.message || {};
			if (!m.ok) return;

			if (m.batch_reset) {
				frappe.show_alert({
					message: __("Batch reset to Draft — run Preview again before posting."),
					indicator: "orange",
				});
				frm.reload_doc();
				return;
			}

			if (reload_panel) {
				wms_paint_batch_tasks_panel(frm, $panel, m);
				frappe.show_alert({ message: __("Task selection updated."), indicator: "green" });
				return;
			}

			const $summary = $panel.find(".text-muted").first();
			if ($summary.length) {
				$summary.text(
					__("{0} task(s) linked · {1} included for post · {2} pending", [
						m.total || 0,
						m.included_count || 0,
						m.pending_count || 0,
					])
				);
			}
		},
	});
}

function wms_render_batch_tasks_panel(frm) {
	wms_remove_batch_tasks_panel(frm);
	if (frm.is_new()) return;

	const $anchor = frm.fields_dict.summary && frm.fields_dict.summary.$wrapper;
	if (!$anchor || !$anchor.length) return;

	const $panel = $(`<div class="${WMS_BATCH_TASKS_PANEL.slice(1)} form-section"></div>`);
	$panel.insertBefore($anchor);
	$panel.html(`<div class="text-muted">${__("Loading linked tasks...")}</div>`);

	frappe.call({
		method: "printechs_wms.api.cycle_count_batch.get_batch_linked_tasks",
		args: { batch_name: frm.doc.name },
		callback: (r) => {
			const m = r.message || {};
			if (!m.ok) {
				$panel.html(`<div class="text-danger">${__("Could not load linked tasks.")}</div>`);
				return;
			}
			wms_paint_batch_tasks_panel(frm, $panel, m);
		},
	});
}

frappe.ui.form.on("WMS Cycle Count Batch", {
	refresh(frm) {
		const status = frm.doc.status || "Draft";
		const isDraft = frm.doc.docstatus === 0;

		wms_render_batch_tasks_panel(frm);

		if (!isDraft || frm.is_new()) return;

		if (status !== "Posted") {
			frm.add_custom_button(__("Load Actual Stock Preview"), () => {
				frappe.call({
					method: "printechs_wms.api.cycle_count_batch.load_actual_stock_preview",
					args: { batch_name: frm.doc.name },
					freeze: true,
					callback: (r) => {
						const m = r.message || {};
						if (m.ok) {
							frappe.msgprint(
								`Preview done. Updated lines: ${m.updated_lines}, Summary rows: ${m.summary_rows}`
							);
							frm.reload_doc();
						}
					},
				});
			});
		}

		if (status === "Previewed") {
			frm.add_custom_button(__("Export Verification Excel"), () => {
				frappe.call({
					method: "printechs_wms.api.cycle_count_batch.export_opening_valuation_template",
					args: { batch_name: frm.doc.name },
					freeze: true,
					freeze_message: __("Generating Excel..."),
					callback: (r) => {
						const m = r.message || {};
						if (!m.ok) {
							frappe.msgprint({
								title: __("Error"),
								message: m.message || __("Export failed."),
								indicator: "red",
							});
							return;
						}
						const missing = m.missing_rate_count
							? `<br>Missing rates: <b>${m.missing_rate_count}</b>`
							: "";
						frappe.msgprint({
							title: __("Verification Excel"),
							message: `Items: <b>${m.item_count}</b>${missing}<br>File: <a href="${m.file_url}" target="_blank">${m.file_name}</a>`,
							indicator: "green",
						});
					},
				});
			}).addClass("btn-primary");

			frm.add_custom_button(__("Upload Verified Excel (Create Reconciliation SR)"), () => {
				const company = frm.doc.company || "";
				frappe.prompt(
					[
						{
							fieldname: "valuation_file",
							fieldtype: "Attach",
							label: __("Verification Excel"),
							reqd: 1,
							description: __(
								"Upload finance-verified Excel. counted_qty must not be changed — valuation_rate only."
							),
						},
						{
							fieldname: "difference_account",
							fieldtype: "Link",
							options: "Account",
							label: __("Difference Account"),
							reqd: 0,
							get_query: () => ({
								filters: [
									["Account", "root_type", "=", "Expense"],
									["Account", "is_group", "=", 0],
									["Account", "company", "=", company],
								],
							}),
						},
					],
					(values) => {
						if (!values || !values.valuation_file) return;
						frappe.call({
							method: "printechs_wms.api.cycle_count_batch.upload_opening_valuation_file",
							args: {
								file_url: values.valuation_file,
								batch_name: frm.doc.name,
								difference_account: values.difference_account,
							},
							freeze: true,
							freeze_message: __("Creating Stock Reconciliation..."),
							callback: (r) => {
								const m = r.message || {};
								if (!m.ok) {
									frappe.msgprint({
										title: __("Error"),
										message: m.message || __("Upload failed."),
										indicator: "red",
									});
									return;
								}
								frappe.msgprint({
									title: __("Stock Reconciliation Created"),
									message: `SR: <b>${m.sr}</b><br>Rows in SR: <b>${m.row_count_in_sr}</b>`,
									indicator: "green",
								});
								frm.reload_doc();
							},
						});
					},
					__("Upload Verified Excel"),
					__("Upload & Create SR")
				);
			});

			frm.add_custom_button(__("Confirm & Post Batch"), () => {
				frappe.confirm(__("Update WMS Stock Balance for this batch?"), () => {
					frappe.call({
						method: "printechs_wms.api.cycle_count_batch.confirm_and_post_batch",
						args: { batch_name: frm.doc.name, create_stock_reconciliation: 0 },
						freeze: true,
						callback: (r) => {
							const m = r.message || {};
							if (!m.ok) {
								frappe.msgprint({
									title: __("Error"),
									message: m.message || __("Posting failed."),
									indicator: "red",
								});
								return;
							}
							frappe.msgprint({
								title: __("Posted"),
								message: `Updated balances: <b>${m.updated_balances}</b><br>Cleared stale cartons: <b>${m.cleared_stale_cartons || 0}</b><br>SR: <b>${m.sr || "N/A"}</b>${
									m.sr_note ? `<br><span class="text-muted">${m.sr_note}</span>` : ""
								}`,
								indicator: "green",
							});
							frm.reload_doc();
						},
					});
				});
			}).addClass("btn-danger");
		}
	},
});
